#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<string> words(n);
    for (int i = 0; i < n; i++) cin >> words[i];
    long long q;
    cin >> q;
    vector<string> prefixes(q);
    for (int i = 0; i < q; i++) cin >> prefixes[i];

    vector<vector<int>> child(1, vector<int>(26, -1));
    vector<int> cnt(1, 0);
    for (const string& w : words) {
        int node = 0;
        for (char c : w) {
            int k = c - 'a';
            if (child[node][k] < 0) {
                int fresh = (int)child.size();
                child[node][k] = fresh;
                child.push_back(vector<int>(26, -1));
                cnt.push_back(0);
            }
            node = child[node][k];
            cnt[node]++;
        }
    }
    for (const string& p : prefixes) {
        int node = 0;
        for (char c : p) {
            node = child[node][c - 'a'];
            if (node < 0) break;
        }
        cout << (node < 0 ? 0 : cnt[node]) << "\n";
    }

    return 0;
}

